// Get the current usage of the cache
size_t current_usage = cache_->GetUsage();

// If the current usage is already less than or equal to the target usage, do nothing
if (current_usage <= target_usage) {
    return;
}

// Calculate the amount of memory that needs to be evicted
size_t amount_to_evict = current_usage - target_usage;

// Iterate over the cache entries and evict the least recently used ones
for (auto it = cache_->GetLRUList().begin(); it != cache_->GetLRUList().end() && amount_to_evict > 0; ++it) {
    // Get the current entry
    LRUHandle* entry = *it;

    // If the entry is not in the cache, skip it
    if (!entry->in_cache) {
        continue;
    }

    // Calculate the charge of the entry
    size_t charge = entry->charge;

    // If the charge of the entry is greater than the amount to evict, evict the entry
    if (charge > amount_to_evict) {
        // Remove the entry from the cache
        cache_->Erase(entry->key());

        // Decrement the amount to evict by the charge of the entry
        amount_to_evict -= charge;
    }
}

